export default "<!doctype html><html lang=\"pt-BR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Stud PB · Editor de pedigree</title><meta name=\"description\" content=\"Edite os dados do animal e exporte seu pedigree em PDF para tela ou celular.\"><style>\n:root{--ink:#382a20;--brown:#795634;--line:#e7e0d8;--muted:#82766b}*{box-sizing:border-box}body{margin:0;background:#f6f5f2;color:var(--ink);font-family:Arial,Helvetica,sans-serif}button,input,select{font:inherit}button{cursor:pointer;border:1px solid var(--line);background:white;color:var(--ink);padding:11px 16px;border-radius:8px;font-size:13px}button:hover{border-color:var(--brown)}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #bf9f76;outline-offset:2px}.primary{background:var(--brown);color:white;border-color:var(--brown)}header{background:#fff;border-bottom:1px solid var(--line);padding:20px 32px;display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{font-size:23px;letter-spacing:3px;font-weight:bold}.brand small{display:block;font-weight:normal;font-size:10px;letter-spacing:2px;margin-top:6px}.tools{display:flex;gap:8px;flex-wrap:wrap}main{display:grid;grid-template-columns:355px minmax(0,1fr);max-width:1800px;margin:auto}.editor{background:white;border-right:1px solid var(--line);padding:26px 24px;max-height:calc(100vh - 87px);overflow:auto;position:sticky;top:0}h1{font-size:21px;margin:0 0 8px}p{font-size:13px;color:var(--muted);line-height:1.6}.hint{font-size:12px}fieldset{border:0;border-bottom:1px solid var(--line);padding:20px 0;margin:0}legend{font-size:11px;font-weight:bold;letter-spacing:1.5px;padding-top:20px;color:var(--brown);text-transform:uppercase}label{display:block;font-size:12px;margin:11px 0 6px;color:#685c50}input,select{width:100%;padding:10px 11px;border:1px solid #ddd6ce;border-radius:7px;background:#fff;color:var(--ink);min-width:0}input:focus,select:focus{border-color:var(--brown)}.row{display:grid;grid-template-columns:1fr 96px;gap:8px}.ancestor{margin:16px 0}.ancestor label{font-size:11px}.preview{padding:28px 32px;min-width:0}.previewbar{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:24px}.eyebrow{font-size:10px;letter-spacing:2px;color:var(--muted);text-transform:uppercase}.previewbar h2{font-size:17px;margin:7px 0 0}.switch{display:flex;background:#eae6df;padding:4px;border-radius:9px}.switch button{border:0;background:transparent;padding:9px 14px}.switch button[aria-pressed=true]{background:#fff;box-shadow:0 1px 4px #0001}#paper{background:white;box-shadow:0 10px 40px #382a2010;border:1px solid var(--line);margin:auto;max-width:1100px}#paper.mobile{max-width:430px}svg{display:block;width:100%;height:auto}.footnote{display:flex;justify-content:space-between;gap:12px;font-size:11px;color:var(--muted);margin-top:14px}.subtools{display:flex;gap:6px;flex-wrap:wrap;margin-top:20px}.subtools button{font-size:11px;padding:9px}#status{min-height:18px;font-size:11px;color:#6f7059;margin:14px 0 0}.privacy{font-size:11px}details{border-bottom:1px solid var(--line);padding:18px 0}summary{cursor:pointer;font-weight:bold;font-size:13px}summary span{display:block;font-weight:normal;font-size:11px;margin-top:5px;color:var(--muted)}.notice{background:#f7f4ee;padding:12px;border-radius:8px;font-size:11px;line-height:1.6;color:#75624f} @media(max-width:900px){main{grid-template-columns:300px 1fr}.preview{padding:24px 16px}header{padding:18px}.previewbar{align-items:flex-start;flex-direction:column}}@media(max-width:680px){main{display:flex;flex-direction:column}.editor{position:static;max-height:none;order:2;border:0;border-top:1px solid var(--line)}.preview{order:1}.previewbar{flex-direction:row;align-items:center}header{align-items:flex-start;flex-direction:column}.tools button{font-size:12px;padding:10px}.brand{font-size:20px}.footnote{flex-direction:column;gap:5px}}\n</style></head><body><header><div class=\"brand\">STUD PB<small>EDITOR DE PEDIGREE</small></div><div class=\"tools\"><button id=\"pdfScreen\" class=\"primary\">Baixar PDF · 16:9</button><button id=\"pdfMobile\">Baixar PDF · 9:16</button></div></header><main><aside class=\"editor\"><h1>Dados do pedigree</h1><p>Preencha os campos. A prévia acompanha cada alteração.</p><form id=\"form\"><fieldset><legend>Animal</legend><label for=\"animalName\">Nome do animal</label><input id=\"animalName\" data-id=\"root\" maxlength=\"100\"><div class=\"row\"><div><label for=\"birth\">Nascimento</label><input id=\"birth\" type=\"date\"></div><div><label for=\"sex\">Sexo</label><select id=\"sex\"><option value=\"F\">Fêmea</option><option value=\"M\">Macho</option></select></div></div></fieldset><div id=\"branches\"></div></form><div class=\"subtools\"><button id=\"saveData\">Salvar dados</button><button id=\"loadData\">Abrir dados</button><button id=\"reset\">Restaurar exemplo</button></div><input id=\"fileInput\" type=\"file\" accept=\".json,application/json\" hidden><p id=\"status\" role=\"status\" aria-live=\"polite\"></p><p class=\"privacy\">Seus dados ficam salvos neste navegador. Use “Salvar dados” para guardar uma cópia e abrir em outro dispositivo.</p><div class=\"notice\">Linha materna primeiro. Os símbolos de sexo são editáveis: confira os dados antes de compartilhar.</div></aside><section class=\"preview\"><div class=\"previewbar\"><div><div class=\"eyebrow\">Prévia em tempo real</div><h2>Pedigree do animal</h2></div><div class=\"switch\" aria-label=\"Formato de visualização\"><button id=\"screen\" aria-pressed=\"true\">Tela 16:9</button><button id=\"mobile\" aria-pressed=\"false\">Mobile 9:16</button></div></div><div id=\"paper\"></div><div class=\"footnote\"><span id=\"dimensions\">1920 × 1080 · Horizontal</span><span>PDF vetorial · Textos selecionáveis</span></div></section></main><script>\nconst embeddedFonts=[{\"b64\": \"\", \"widths\": [318, 401, 460, 838, 636, 950, 780, 275, 390, 390, 500, 838, 318, 361, 318, 337, 636, 636, 636, 636, 636, 636, 636, 636, 636, 636, 337, 337, 838, 838, 838, 531, 1000, 684, 686, 698, 770, 632, 575, 775, 752, 295, 295, 656, 557, 863, 748, 787, 603, 787, 695, 635, 611, 732, 684, 989, 685, 611, 685, 390, 337, 390, 838, 500, 500, 613, 635, 550, 635, 615, 352, 635, 634, 278, 278, 579, 278, 974, 634, 612, 635, 635, 411, 521, 392, 634, 592, 818, 592, 592, 525, 636, 337, 636, 838, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 318, 401, 636, 636, 636, 636, 337, 500, 500, 1000, 471, 612, 838, 361, 1000, 500, 500, 838, 401, 401, 500, 636, 636, 318, 500, 401, 471, 612, 969, 969, 969, 531, 684, 684, 684, 684, 684, 684, 974, 698, 632, 632, 632, 632, 295, 295, 295, 295, 775, 748, 787, 787, 787, 787, 787, 838, 787, 732, 732, 732, 732, 611, 605, 630, 613, 613, 613, 613, 613, 613, 982, 550, 615, 615, 615, 615, 278, 278, 278, 278, 612, 634, 612, 612, 612, 612, 612, 838, 612, 634, 634, 634, 634, 592, 635, 592]}, {\"b64\": \"\", \"widths\": [348, 456, 521, 838, 696, 1002, 872, 306, 457, 457, 523, 838, 380, 415, 380, 365, 696, 696, 696, 696, 696, 696, 696, 696, 696, 696, 400, 400, 838, 838, 838, 580, 1000, 774, 762, 734, 830, 683, 683, 821, 837, 372, 372, 775, 637, 995, 837, 850, 733, 850, 770, 720, 682, 812, 774, 1103, 771, 724, 725, 457, 365, 457, 838, 500, 500, 675, 716, 593, 716, 678, 435, 716, 712, 343, 343, 665, 343, 1042, 712, 687, 716, 716, 493, 595, 478, 712, 652, 924, 645, 652, 582, 712, 365, 712, 838, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 600, 348, 456, 696, 696, 636, 696, 365, 500, 500, 1000, 564, 646, 838, 415, 1000, 500, 500, 838, 438, 438, 500, 736, 636, 380, 500, 438, 564, 646, 1035, 1035, 1035, 580, 774, 774, 774, 774, 774, 774, 1085, 734, 683, 683, 683, 683, 372, 372, 372, 372, 838, 837, 850, 850, 850, 850, 850, 838, 850, 812, 812, 812, 812, 724, 738, 719, 675, 675, 675, 675, 675, 675, 1048, 593, 678, 678, 678, 678, 343, 343, 343, 343, 687, 712, 687, 687, 687, 687, 687, 838, 687, 712, 712, 712, 712, 652, 716, 652]}];\nconst defaults={name:'Balou Blue PB',sex:'M',birth:'2025-12-02',nodes:[{id:'m',name:'Balance Z',sex:'F'},{id:'mm',name:'Daphne',sex:'F'},{id:'mmm',name:'Wildemeid',sex:'F'},{id:'mmf',name:'Stakkato',sex:'M'},{id:'mf',name:'Balou du Rouet',sex:'M'},{id:'mfm',name:'Georgia',sex:'F'},{id:'mff',name:'Baloubet du Rouet',sex:'M'},{id:'f',name:'Chacco Blue',sex:'M'},{id:'fm',name:\"MoM’s Contara\",sex:'F'},{id:'fmm',name:'Godahra II',sex:'F'},{id:'fmf',name:'Contender',sex:'M'},{id:'ff',name:'Chambertin',sex:'M'},{id:'ffm',name:'Desiree VII',sex:'F'},{id:'fff',name:'Cambridge',sex:'M'}]};\nlet data=structuredClone(defaults),mode='screen';const key='studpb-pedigree-v1';try{const saved=JSON.parse(localStorage.getItem(key));if(valid(saved))data=saved}catch{}function valid(d){return d&&typeof d.name==='string'&&d.name.length<=100&&['F','M'].includes(d.sex)&&typeof d.birth==='string'&&(!d.birth||/^\\d{4}-\\d{2}-\\d{2}$/.test(d.birth))&&Array.isArray(d.nodes)&&d.nodes.length===14&&defaults.nodes.every(n=>d.nodes.filter(v=>v.id===n.id&&typeof v.name==='string'&&v.name.length<=100&&['F','M'].includes(v.sex)).length===1)}\nconst $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));function node(id){return data.nodes.find(n=>n.id===id)}\nfunction buildForm(){$('animalName').value=data.name;$('birth').value=data.birth;$('sex').value=data.sex;$('branches').innerHTML=['m','f'].map((side,i)=>`<details open><summary>${i?'Linha paterna':'Linha materna'}<span>${i?'Pai, avós e bisavós paternos':'Mãe, avós e bisavós maternos'}</span></summary>${[side,side+'m',side+'mm',side+'mf',side+'f',side+'fm',side+'ff'].map((id,j)=>{let n=node(id);return `<div class=\"ancestor\"><label for=\"n-${id}\">${j===0?(i?'Pai':'Mãe'):j===1?'Avó':j===4?'Avô':id.endsWith('m')?'Bisavó':'Bisavô'}</label><div class=\"row\"><input id=\"n-${id}\" data-node=\"${id}\" maxlength=\"100\" value=\"${esc(n.name)}\" aria-label=\"Nome ${id}\"><select data-sex=\"${id}\" aria-label=\"Sexo de ${esc(n.name)}\"><option value=\"F\" ${n.sex==='F'?'selected':''}>Fêmea</option><option value=\"M\" ${n.sex==='M'?'selected':''}>Macho</option></select></div></div>`}).join('')}</details>`).join('')}\nfunction persist(){try{localStorage.setItem(key,JSON.stringify(data));$('status').textContent='Alterações salvas neste navegador.'}catch{$('status').textContent='Use Salvar dados para guardar suas alterações.'}render()}\n$('form').addEventListener('input',e=>{let t=e.target;if(t.id==='animalName')data.name=t.value;else if(t.id==='birth')data.birth=t.value;else if(t.id==='sex')data.sex=t.value;else if(t.dataset.node)node(t.dataset.node).name=t.value;else if(t.dataset.sex)node(t.dataset.sex).sex=t.value;persist()});\nfunction textWidth(s,size,bold=false){const widths=embeddedFonts[bold?1:0].widths;return [...String(s)].reduce((sum,c)=>{const code=c.replace(/[’‘]/g,\"'\").replace(/[“”]/g,'\"').charCodeAt(0);return sum+(widths[code-32]??widths[31]??600)},0)*size/1000}\nfunction scene(format){let W=format==='screen'?1920:1080,H=format==='screen'?1080:1920,p=[];const brown='#795634',ink='#382a20',muted='#968573',line='#cbbbA7';const rect=(x,y,w,h,fill,r=0)=>p.push({t:'rect',x,y,w,h,fill,r});const ln=(x1,y1,x2,y2,color=line,width=1.8)=>p.push({t:'line',x1,y1,x2,y2,color,width});const tx=(s,x,y,size,color=ink,bold=false,max=9999)=>{s=s||'Não informado';size=Math.min(size,max/textWidth(s,1,bold));p.push({t:'text',s,x,y,size,color,bold});return x+textWidth(s,size,bold)};\nfunction symbol(sex,x,y,z=34){rect(x,y-z*.72,z,z*.86,brown,6);let cx=x+z*.43,cy=y-z*.34,r=z*.15; // circle represented by Bezier in both exports\np.push({t:'circle',x:cx,y:cy,r,color:'#ffffff',width:1.7});if(sex==='M'){ln(cx+r*.7,cy-r*.7,cx+r*2.2,cy-r*2.2,'#ffffff',1.7);ln(cx+r*.9,cy-r*2.2,cx+r*2.2,cy-r*2.2,'#ffffff',1.7);ln(cx+r*2.2,cy-r*.9,cx+r*2.2,cy-r*2.2,'#ffffff',1.7)}else{ln(cx,cy+r,cx,cy+r*2.65,'#ffffff',1.7);ln(cx-r*.8,cy+r*1.95,cx+r*.8,cy+r*1.95,'#ffffff',1.7)}}\nfunction animal(id,x,y,size=28,max=400){let n=node(id);symbol(n.sex,x,y);return tx(n.name,x+50,y,size,ink,id.length===1,max-50)}\nrect(0,0,W,H,'#ffffff');tx('STUD PB  /  PEDIGREE',format==='screen'?100:72,format==='screen'?77:84,18,brown,true);let title=data.name||'Nome do animal';tx(title,format==='screen'?100:72,format==='screen'?164:185,format==='screen'?66:62,brown,true,W-(format==='screen'?200:144));let date='';if(data.birth){const d=new Date(data.birth+'T12:00:00');if(!isNaN(d))date=d.toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'})}tx((data.sex==='F'?'Fêmea':'Macho')+(date?'  |  '+date:''),format==='screen'?103:74,format==='screen'?214:245,format==='screen'?25:26,muted);ln(format==='screen'?100:72,format==='screen'?254:292,W-(format==='screen'?100:72),format==='screen'?254:292);\nif(format==='screen'){tx('MÃE / PAI',100,308,16,muted);tx('AVÓS',660,308,16,muted);tx('BISAVÓS',1260,308,16,muted);['m','f'].forEach((s,i)=>{let top=360+i*320;let root=top+125;const parentEnd=animal(s,100,root,36,430);ln(parentEnd+16,root-10,600,root-10);ln(600,top+45,600,top+205);['m','f'].forEach((a,j)=>{let y=top+45+j*160;ln(600,y,640,y);const ancestorEnd=animal(s+a,660,y+10,29,440);ln(ancestorEnd+16,y,1190,y);ln(1190,y-42,1190,y+42);['m','f'].forEach((b,k)=>{let yy=y-42+k*84;ln(1190,yy,1240,yy);animal(s+a+b,1260,yy+10,27,550);ln(1310,yy+31,1815,yy+31,'#e9e3dc',1)})})})}else{['m','f'].forEach((s,i)=>{let top=342+i*720;rect(60,top,960,660,'#faf8f5',18);tx(i?'LINHA PATERNA':'LINHA MATERNA',90,top+49,16,muted,true);animal(s,90,top+112,39,850);ln(90,top+151,990,top+151);['m','f'].forEach((a,j)=>{let cy=top+295+j*240;const ancestorEnd=animal(s+a,92,cy,29,360);ln(ancestorEnd+14,cy-10,490,cy-10);ln(490,cy-62,490,cy+42);['m','f'].forEach((b,k)=>{let yy=cy-62+k*104;ln(490,yy,520,yy);animal(s+a+b,540,yy+10,27,440)})})})}\nln(format==='screen'?100:72,H-85,W-(format==='screen'?100:72),H-85);tx('STUD PB',format==='screen'?100:72,H-45,17,brown,true);tx('3 gerações  |  Linhagem materna primeiro',format==='screen'?1330:480,H-45,16,muted);return {W,H,p}}\nfunction svg(sc){return `<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 ${sc.W} ${sc.H}\" role=\"img\" aria-label=\"Pedigree de ${esc(data.name)}\"><defs><style>@font-face{font-family:Pedigree;src:url(data:font/ttf;base64,${embeddedFonts[0].b64})} @font-face{font-family:Pedigree;src:url(data:font/ttf;base64,${embeddedFonts[1].b64});font-weight:700}</style></defs>${sc.p.map(o=>o.t==='rect'?`<rect x=\"${o.x}\" y=\"${o.y}\" width=\"${o.w}\" height=\"${o.h}\" rx=\"${o.r}\" fill=\"${o.fill}\"/>`:o.t==='line'?`<line x1=\"${o.x1}\" y1=\"${o.y1}\" x2=\"${o.x2}\" y2=\"${o.y2}\" stroke=\"${o.color}\" stroke-width=\"${o.width}\"/>`:o.t==='circle'?`<circle cx=\"${o.x}\" cy=\"${o.y}\" r=\"${o.r}\" fill=\"none\" stroke=\"${o.color}\" stroke-width=\"${o.width}\"/>`:`<text x=\"${o.x}\" y=\"${o.y}\" font-family=\"Pedigree,Arial,sans-serif\" font-size=\"${o.size}\" font-weight=\"${o.bold?700:400}\" fill=\"${o.color}\">${esc(o.s)}</text>`).join('')}</svg>`}\nfunction render(){$('paper').className=mode==='mobile'?'mobile':'';$('paper').innerHTML=svg(scene(mode));$('dimensions').textContent=mode==='screen'?'1920 × 1080 · Horizontal':'1080 × 1920 · Vertical';['screen','mobile'].forEach(id=>$(id).setAttribute('aria-pressed',id===mode))}['screen','mobile'].forEach(id=>$(id).onclick=()=>{mode=id;render()});\n// Dependency-free vector PDF. WinAnsi preserves Portuguese accents; gender symbols are drawn as paths.\nfunction pdf(sc){let ops=[];let num=n=>(Math.round(n*100)/100).toString();let rgb=h=>h.slice(1).match(/../g).map(v=>num(parseInt(v,16)/255)).join(' ');let yy=y=>sc.H-y;let latin=s=>s.replace(/[’‘]/g,\"'\").replace(/[“”]/g,'\"').replace(/[^\\x20-\\xFF]/g,'?').replace(/([\\\\()])/g,'\\\\$1');const line=(x1,y1,x2,y2)=>`${num(x1)} ${num(yy(y1))} m ${num(x2)} ${num(yy(y2))} l`;for(let o of sc.p){if(o.t==='text')ops.push(`BT /${o.bold?'F2':'F1'} ${num(o.size)} Tf ${rgb(o.color)} rg 1 0 0 1 ${num(o.x)} ${num(yy(o.y))} Tm (${latin(o.s)}) Tj ET`);else if(o.t==='line')ops.push(`${rgb(o.color)} RG ${o.width} w ${line(o.x1,o.y1,o.x2,o.y2)} S`);else if(o.t==='circle'){let {x,y,r}=o,c=r*.55228475;ops.push(`${rgb(o.color)} RG ${o.width} w ${num(x+r)} ${num(yy(y))} m ${num(x+r)} ${num(yy(y-c))} ${num(x+c)} ${num(yy(y-r))} ${num(x)} ${num(yy(y-r))} c ${num(x-c)} ${num(yy(y-r))} ${num(x-r)} ${num(yy(y-c))} ${num(x-r)} ${num(yy(y))} c ${num(x-r)} ${num(yy(y+c))} ${num(x-c)} ${num(yy(y+r))} ${num(x)} ${num(yy(y+r))} c ${num(x+c)} ${num(yy(y+r))} ${num(x+r)} ${num(yy(y+c))} ${num(x+r)} ${num(yy(y))} c S`)}else{let{x,y,w,h,r}=o,Y=yy(y+h);let path=r?`${x+r} ${Y} m ${x+w-r} ${Y} l ${x+w} ${Y} ${x+w} ${Y} ${x+w} ${Y+r} c ${x+w} ${Y+h-r} l ${x+w} ${Y+h} ${x+w} ${Y+h} ${x+w-r} ${Y+h} c ${x+r} ${Y+h} l ${x} ${Y+h} ${x} ${Y+h} ${x} ${Y+h-r} c ${x} ${Y+r} l ${x} ${Y} ${x} ${Y} ${x+r} ${Y} c h`:`${x} ${Y} ${w} ${h} re`;ops.push(`${rgb(o.fill)} rg ${path} f`)}}let stream=ops.join('\\n');let objs=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>',`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${sc.W} ${sc.H}] /Resources << /Font << /F1 4 0 R /F2 5 0 R >> >> /Contents 6 0 R >>`,`<< /Type /Font /Subtype /TrueType /BaseFont /DejaVuSans /Encoding /WinAnsiEncoding /FirstChar 32 /LastChar 255 /Widths [${embeddedFonts[0].widths.join(' ')}] /FontDescriptor 7 0 R >>`,`<< /Type /Font /Subtype /TrueType /BaseFont /DejaVuSans-Bold /Encoding /WinAnsiEncoding /FirstChar 32 /LastChar 255 /Widths [${embeddedFonts[1].widths.join(' ')}] /FontDescriptor 8 0 R >>`,`<< /Length ${stream.length} >>\\nstream\\n${stream}\\nendstream`];objs.push(...['DejaVuSans','DejaVuSans-Bold'].map((name,i)=>`<< /Type /FontDescriptor /FontName /${name} /Flags 32 /FontBBox [-1100 -500 2200 1300] /ItalicAngle 0 /Ascent 928 /Descent -236 /CapHeight 729 /StemV 80 /FontFile2 ${9+i} 0 R >>`),...embeddedFonts.map(f=>{const raw=atob(f.b64);return `<< /Length ${raw.length} /Length1 ${raw.length} >>\\nstream\\n${raw}\\nendstream`}));let out='%PDF-1.4\\n',offsets=[0];objs.forEach((o,i)=>{offsets.push(out.length);out+=`${i+1} 0 obj\\n${o}\\nendobj\\n`});let start=out.length;out+=`xref\\n0 11\\n0000000000 65535 f \\n${offsets.slice(1).map(n=>String(n).padStart(10,'0')+' 00000 n \\n').join('')}trailer\\n<< /Size 11 /Root 1 0 R >>\\nstartxref\\n${start}\\n%%EOF`;return Uint8Array.from(out,c=>c.charCodeAt(0))}\nfunction download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}function slug(){return (data.name||'animal').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'-').replace(/^-|-$/g,'')}\n$('pdfScreen').onclick=()=>download(new Blob([pdf(scene('screen'))],{type:'application/pdf'}),slug()+'-16x9.pdf');$('pdfMobile').onclick=()=>download(new Blob([pdf(scene('mobile'))],{type:'application/pdf'}),slug()+'-9x16.pdf');$('saveData').onclick=()=>download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),slug()+'-dados.json');$('loadData').onclick=()=>$('fileInput').click();$('fileInput').onchange=async e=>{try{const d=JSON.parse(await e.target.files[0].text());if(!valid(d))throw Error();data=d;buildForm();persist();$('status').textContent='Dados importados com sucesso.'}catch{$('status').textContent='Arquivo inválido. Abra um JSON salvo por este editor.'}e.target.value=''};$('reset').onclick=()=>{if(confirm('Restaurar o exemplo Balou Blue PB? Salve os dados atuais se quiser guardá-los.')){data=structuredClone(defaults);buildForm();persist()}};buildForm();render();\n</script></body></html>\n";
